parameters.jsCode:
const limits = $('Resolve Slot Spec').first().json.limits || {};
const lex = $('Resolve Slot Spec').first().json.profile?.message?.lexicon || {};
const out = ($json.output || $json).variants || [];
const kept = [], rejected = [];
for (const v of out) {
  const text = [v.hook, v.body, v.cta].filter(Boolean).join('\n');
  const issues = [];
  if (limits.max_chars && text.length > limits.max_chars) issues.push('over_max_chars');
  if (limits.hashtags_max && (v.hashtags || []).length > limits.hashtags_max) v.hashtags = (v.hashtags || []).slice(0, limits.hashtags_max);
  for (const b of (lex.banned || [])) if (text.toLowerCase().includes(b.toLowerCase())) issues.push('banned_term:' + b);
  const rec = { ...v, char_count: text.length, issues };
  (issues.length ? rejected : kept).push(rec);
}
return [{ json: { variants: kept, rejected, produced: out.length, usable: kept.length } }];

// GENERATED epilogue — appends exactly one provenance entry and closes the span.
// Provenance is append-only; nothing in the estate is permitted to rewrite an earlier entry.
const e = $('Envelope In').first().json;
const out = $json;
const duration = Date.now() - (e._started_at ?? Date.now());
const entry = {
  capability: "copy.short.generate",
  version: "1.0.0",
  at: new Date().toISOString(),
  duration_ms: duration,
  model: out._model ?? null,
  provider: out._provider ?? null,
  cost_minor_units: out._cost_minor_units ?? 1,
  inputs_hash: e.idempotency_key,
  decision_id: out.decision?.decision_id ?? null
};
return [{ json: {
  ...out,
  _envelope: {
    ...e,
    span_id: e.parent_span_id,
    provenance: [...(e.provenance ?? []), entry],
    budget: { ...(e.budget ?? {}), spent_minor_units: (e.budget?.spent_minor_units ?? 0) + (entry.cost_minor_units ?? 0) }
  },
  _telemetry: {
    event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
    trace_id: e.trace_id, span_id: e.span_id, tenant_id: e.tenant_id,
    capability: "copy.short.generate", capability_version: "1.0.0",
    layer: "terminal", event: 'span_end', status: out.error ? 'error' : 'ok',
    duration_ms: duration, cost_minor_units: entry.cost_minor_units,
    error_code: out.error?.code ?? null, at: new Date().toISOString()
  }
} }];

